import log from 'loglevel';

const LOG_LEVEL = (process.env.LOG_LEVEL || 'INFO').toUpperCase();

let _onError:
  | ((message: string, args: unknown[], service: string | undefined) => void)
  | null = null;

export const registerErrorCapture = (
  fn: (message: string, args: unknown[], service: string | undefined) => void,
) => {
  _onError = fn;
};

export const setLogLevel = (level: string) => {
  const LOG_LEVEL = level.toUpperCase();
  log.setLevel(
    log.levels[LOG_LEVEL as keyof typeof log.levels] || log.levels.INFO,
  );
};

export const redirectLogsToStderr = () => {
  log.methodFactory = (_methodName, _logLevel, _loggerName) => {
    return (message: string, ...args: unknown[]) => {
      const formatted =
        args.length > 0 ? `${message} ${args.map(String).join(' ')}` : message;
      process.stderr.write(formatted + '\n');
    };
  };
  log.setLevel(log.getLevel());
};

log.setLevel(
  log.levels[LOG_LEVEL as keyof typeof log.levels] || log.levels.INFO,
);

if (process.env.NODE_ENV !== 'production') {
  const originalFactory = log.methodFactory;
  log.methodFactory = (methodName, logLevel, loggerName) => {
    const rawMethod = originalFactory(methodName, logLevel, loggerName);

    const emojis = {
      trace: '🔍',
      debug: '🐛',
      info: '📋',
      warn: '⚠️',
      error: '❌',
    };

    return (message: string, ...args: unknown[]) => {
      const emoji = emojis[methodName as keyof typeof emojis] || '';
      const timestamp = new Date().toISOString();
      rawMethod(`${emoji} [${timestamp}] ${message}`, ...args);
    };
  };
  log.setLevel(log.getLevel());
}

export const createLogger = (serviceName?: string) => {
  const prefix = serviceName ? `[${serviceName}] ` : '';

  return {
    trace: (message: string, ...args: unknown[]) =>
      log.trace(`${prefix}${message}`, ...args),
    debug: (message: string, ...args: unknown[]) =>
      log.debug(`${prefix}${message}`, ...args),
    info: (message: string, ...args: unknown[]) =>
      log.info(`${prefix}${message}`, ...args),
    warn: (message: string, ...args: unknown[]) =>
      log.warn(`${prefix}${message}`, ...args),
    error: (message: string, ...args: unknown[]) => {
      log.error(`${prefix}${message}`, ...args);
      try {
        _onError?.(message, args, serviceName);
      } catch (e) {
        process.stderr.write(`[logger] _onError callback threw: ${e}\n`);
      }
    },

    project: (projectId: string, message: string, ...args: unknown[]) =>
      log.info(`${prefix}[${projectId}] ${message}`, ...args),

    api: (method: string, url: string, message: string, ...args: unknown[]) =>
      log.info(`${prefix}${method} ${url} - ${message}`, ...args),
  };
};
